// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · TYT Matematik: yüzde, kâr-zarar, karışım, hareket problemleri (zor).
const ozExam10Zor = <(String, String, List<String>, String)>[
  ('Bir ürünün fiyatı %20 düşünce aynı parayla eskisinden 15 adet fazla ürün alınabiliyor. İndirimden önce bu parayla kaç ürün alınabiliyordu?', '60', ['75', '48', '62,5'], 'Fiyat 0,8 katına inince adet 1,25 katına çıkar; artış %25\'tir. 15 adet %25\'e karşılık geldiğinden eski adet 60\'tır.'),
  ('Bir seçmen grubunun %60\'ı A adayını destekliyor. A\'yı destekleyenlerin %10\'u ve desteklemeyenlerin %30\'u fikir değiştiriyor. Bu değişimden sonra A\'yı destekleyenlerin oranı yüzde kaçtır?', '%66', ['%54', '%60', '%72,5'], 'A\'dan ayrılan: 0,6 × 0,1 = 0,06. A\'ya geçen: 0,4 × 0,3 = 0,12. Yeni oran 0,60 − 0,06 + 0,12 = %66.'),
  ('Bir ülkede KDV oranı %10\'dan %20\'ye çıkarılıyor. KDV hariç fiyatı değişmeyen bir ürünün tüketiciye maliyeti yüzde kaç artar?', 'Yaklaşık %9,1', ['Tam olarak %10', '%100', 'Yaklaşık %8,3'], 'Eski fiyat 1,10P, yeni 1,20P: artış 0,10/1,10 ≈ %9,1.'),
  ('Bir işçinin brüt maaşından %15 gelir vergisi, kalan tutardan da %10 sigorta primi kesiliyor. Eline 15.300 TL geçtiğine göre brüt maaşı kaç TL\'dir?', '20.000', ['19.125', '18.000', '21.176,5'], 'Net = B × 0,85 × 0,90 = 0,765B ⇒ B = 15.300/0,765 = 20.000.'),
  ('Bir ürünü 900 TL\'ye satan bir satıcı, satış fiyatı üzerinden %15 zarar etmiştir. Maliyet kaç TL\'dir?', '1035', ['1058,8', '765', '1000'], 'Zarar satış fiyatına göredir: 0,15 × 900 = 135 TL; maliyet 900 + 135 = 1035 TL.'),
  ('Etiket fiyatından %30 indirimle satılan bir ürün maliyetine satılmış olmaktadır. İndirim yapılmasaydı kâr oranı yüzde kaç olurdu?', '%42,86 (yaklaşık)', ['%30 (tam olarak)', '%70', '%43,5 (yaklaşık)'], '0,7E = M ⇒ E = M/0,7 ≈ 1,4286M; kâr oranı ≈ %42,86.'),
  ('Bir satıcı yumurtaların 10 tanesini 30 TL\'ye alıyor. Tanesini kaç TL\'ye satarsa satış fiyatı üzerinden %25 kâr elde eder?', '4', ['3,75', '3,6', '5'], 'Tane maliyeti 3 TL; S − 3 = 0,25S ⇒ S = 4 TL.'),
  ('Bir konser organizatörünün sabit gideri 150.000 TL, bilet başına değişken gideri 50 TL\'dir. Bilet fiyatı 300 TL ise 1000 bilet satıldığında kâr, toplam gelirin yüzde kaçı olur?', '%33,3̅', ['%40', '%50', '%33,75'], 'Gelir 300.000, gider 150.000 + 50.000 = 200.000; kâr 100.000 ⇒ 100/300 = 1/3.'),
  ('Bir emekli maaşı %10 artırılmış ancak yıllık enflasyon %32 olmuştur. Emeklinin alım gücü yüzde kaç azalmıştır?', '%16,6̅ (yaklaşık %16,7)', ['%22', '%20', '%12,4 (yaklaşık)'], '1,10/1,32 ≈ 0,833 ⇒ alım gücü yaklaşık %16,7 azalmıştır.'),
  ('Kütlece %10\'luk bir tuzlu suyun tuz oranını iki katına çıkarmak için suyun en az yüzde kaçı buharlaştırılmalıdır? (Yüzde, başlangıçtaki suya göredir.)', 'Yaklaşık %55,6', ['%50', '%10', 'Yaklaşık %44,4'], '100 g\'da 10 g tuz, 90 g su. %20 için toplam 50 g yani su 40 g kalmalı; 50 g su uçar: 50/90 ≈ %55,6.'),
  ('Saf zeytinyağıyla dolu 50 litrelik bir varilden üç kez 10\'ar litre alınıp her seferinde yerine ayçiçek yağı konuyor. Son durumda varilde kaç litre zeytinyağı kalır?', '25,6', ['26,25', '30', '24,4'], 'Her işlemde kalan oran 4/5: 50 × (4/5)³ = 25,6 litre.'),
  ('Kilogramı 40 TL olan arpa ile kilogramı 70 TL olan buğday eşit tutarlarda (her birinden 2800\'er TL\'lik) alınıp karıştırılıyor. Karışımın kilogram maliyeti kaç TL\'dir?', '50,9 (yaklaşık)', ['55', '52,5', '48,7 (yaklaşık)'], 'Arpa 70 kg, buğday 40 kg; 5600/110 ≈ 50,9 TL. Eşit tutarda karıştırmada ortalama basit ortalamadan küçüktür.'),
  ('Kalay oranı %20 olan 50 kg bronzu, kalay oranı %12 olan bronza dönüştürmek için kaç kg bakır eklenmelidir?', '33,3̅', ['30', '40', '25,5'], 'Kalay 10 kg; 10/0,12 ≈ 83,3 kg alaşım gerekir. Eklenecek bakır ≈ 33,3 kg.'),
  ('Kütlece %99\'u su olan 100 kg salatalık bir süre bekletilince su oranı %98\'e düşüyor. Salatalıkların yeni kütlesi kaç kg\'dır?', '50', ['99', '98', '75,5'], 'Kuru madde 1 kg sabittir; yeni durumda bu %2\'ye karşılık gelir: 1/0,02 = 50 kg.'),
  ('Taze mantarın %90\'ı, kurutulmuş mantarın %12\'si sudur. 22 kg taze mantardan kaç kg kuru mantar elde edilir?', '2,5', ['2,2', '2,64', '3,5'], 'Kuru madde 2,2 kg; kuru mantarda bu %88\'dir: 2,2/0,88 = 2,5 kg.'),
  ('A ve B kentlerinden karşılıklı aynı anda yola çıkan iki araç karşılaştıktan sonra A\'dan çıkan araç B\'ye 4 saatte, B\'den çıkan araç A\'ya 1 saatte varıyor. Araçlar yola çıktıktan kaç saat sonra karşılaşmıştır?', '2', ['2,5', '1,5', '3'], 'Klasik sonuç: karşılaşma süresi t² = 4 × 1 ⇒ t = 2 saat.'),
  ('Bir yük treni saatte 50 km hızla gidiyor. Aynı istasyondan 1 saat 12 dakika sonra aynı yönde çıkan bir hızlı tren yük trenine 3 saatte yetişiyor. Hızlı trenin hızı saatte kaç km\'dir?', '70', ['60', '72,5', '80'], 'Yük treni 1,2 saatte 60 km önde. Yetişme 3 saatte ⇒ hız farkı 20 km/sa; hızlı tren 70 km/sa.'),
  ('Bir yolun yarısını saatte 40 km hızla giden bir sürücü, yolun tamamında ortalama 80 km/sa hıza ulaşmak istiyor. Bu hedef için hangisi doğrudur?', 'Hedefe ulaşılamaz; kalan yarıyı sıfır sürede gitmek gerekir.', ['Kalan yarıyı saatte 120 km hızla gitmelidir.', 'Kalan yarıyı saatte 160 km hızla gitmelidir.', 'Kalan yarıyı saatte 240 km hızla gitmelidir.'], 'Yol 2d olsun; ilk yarı d/40 saat sürer. Ortalama 80 için toplam süre 2d/80 = d/40 olmalıdır; kalan yarıya hiç süre kalmaz.'),
  ('Bir koşucu 6 km\'lik parkurun ilk 2 km\'sini saatte 8 km, kalanını saatte 12 km hızla koşuyor. Ortalama hızı saatte kaç km\'dir?', '10,29 (yaklaşık)', ['10', '10,67 (yaklaşık)', '11'], 'Süre 2/8 + 4/12 = 0,25 + 0,333 = 0,583 saat; 6/0,583 ≈ 10,29 km/sa.'),
  ('Çevresi 500 m olan bir pistte aynı noktadan aynı anda zıt yönlere yürüyen iki kişi 4 dakika sonra karşılaşıyor. Aynı yöne yürüselerdi hızlı olan yavaş olana 20 dakikada yetişecekti. Hızlı olanın hızı dakikada kaç metredir?', '75', ['62,5', '50', '100'], 'Toplam hız 500/4 = 125, hız farkı 500/20 = 25 m/dk. Hızlı olan (125 + 25)/2 = 75 m/dk.'),
  ('Bir yarış pistinde iki araç aynı noktadan aynı anda aynı yöne çıkıyor. Biri turunu 60, diğeri 75 saniyede tamamlıyor. Hızlı araç ilk kez kaç saniye sonra yavaş aracın bir tur önüne geçer?', '300', ['150', '337,5', '375'], 'Hızlı araç her saniye 1/60 − 1/75 = 1/300 tur fark açar; bir tur fark 300 saniyede olur.'),
  ('Bir tekneden akıntıya karşı giderken suya bir şişe düşüyor. Tekne 30 dakika daha aynı yönde gidip geri dönüyor ve şişeyi yakalıyor. Şişe düştükten kaç dakika sonra yakalanır? (Teknenin suya göre hızı sabittir.)', '60', ['30', '45', 'Akıntı hızına bağlıdır.'], 'Suya göre düşünülürse şişe duruyor gibidir; tekne 30 dakika uzaklaşıp aynı hızla 30 dakikada döner. Toplam 60 dakika.'),
  ('Uzunluğu 180 m olan bir tren, 900 m\'lik bir tünelde tamamen içeride kaldığı süreyi ölçmek istiyor. Tren saniyede 20 m hızla gidiyorsa tren tünelin tamamen içinde kaç saniye kalır?', '36', ['45', '54', '40,5'], 'Tamamen içeride olma, arka uç girdikten ön uç çıkana kadardır: (900 − 180)/20 = 36 s.'),
  ('Bir trende oturan yolcu, karşı yönden gelen 240 m uzunluğundaki bir trenin penceresinin önünden 6 saniyede geçtiğini görüyor. Yolcunun treni saatte 72 km hızla gidiyorsa diğer tren saatte kaç km hızla gitmektedir?', '72', ['40', '144', '54'], 'Göreli hız 240/6 = 40 m/s = 144 km/sa. Diğer tren 144 − 72 = 72 km/sa.'),
  ('Hızını saatte 15 km artıran bir sürücü 300 km\'lik yolu 1 saat erken tamamlıyor. Sürücünün ilk hızı saatte kaç km\'dir?', '60', ['75', '45', '62,5'], '300/v − 300/(v + 15) = 1 ⇒ v² + 15v − 4500 = 0 ⇒ v = 60.'),
  ('Her gün aynı saatte evden çıkan bir öğrenci dakikada 50 m yürüyünce 4 dakika geç, dakikada 70 m yürüyünce 4 dakika erken varıyor. Ders başlangıcına kadar evden çıktığı andan itibaren kaç dakikası vardır?', '24', ['28', '20', '25,5'], 'x/50 − x/70 = 8 ⇒ 20x/3500 = 8 ⇒ x = 1400 m. Süre 1400/50 − 4 = 24 dk.'),
  ('Bir yolcu treni, bir arıza nedeniyle yolun ortasında 12 dakika bekledikten sonra kalan 60 km\'yi hızını saatte 10 km artırarak gidip zamanında varıyor. Trenin normal hızı saatte kaç km\'dir?', '50', ['60', '40', '52,5'], '60/v − 60/(v + 10) = 1/5 ⇒ v² + 10v − 3000 = 0 ⇒ v = 50 km/sa.'),
  ('Bir koşucu hızını %10 artırarak bir parkuru 3 dakika daha kısa sürede tamamlıyor. Parkuru eski hızıyla kaç dakikada koşuyordu?', '33', ['30', '27', '33,5'], 'Yeni süre t/1,1. t − t/1,1 = 3 ⇒ t × 0,1/1,1 = 3 ⇒ t = 33 dk.'),
  ('Bir havalimanında 60 m\'lik yürüyen bant saniyede 1 m hızla çalışıyor. Bant yanındaki zeminde saniyede 1,5 m yürüyen biriyle, bantta aynı hızla yürüyen arkadaşı aynı anda başlıyor. Banttaki kişi bandın sonuna geldiğinde zemindeki kişi kaç metre gerisindedir?', '24', ['36', '20', '62,5'], 'Banttaki kişinin hızı 2,5 m/s; 60/2,5 = 24 s\'de varır. Zemindeki kişi 24 × 1,5 = 36 m yürümüştür; 60 − 36 = 24 m geride.'),
  ('Bir yarışta 100 m\'yi koşan iki atletten Ali bitirdiğinde Burak 10 m geride kalıyor. Hızlar sabitse Ali\'nin Burak\'la aynı anda bitirmesi için başlangıç çizgisinin kaç metre gerisinden başlaması gerekir?', 'Yaklaşık 11,1', ['10', '9', '12,5'], 'Hız oranı 10 : 9. Ali\'nin koşacağı x için x/10 = 100/9 ⇒ x ≈ 111,1 m; yani 11,1 m geriden başlamalı.'),
  ('Bir yarışta 1000 m\'yi koşan A, bitiş çizgisine geldiğinde B\'yi 100 m, C\'yi 190 m geride bırakıyor. B bitiş çizgisine geldiğinde C kaç metre gerisindedir? (Hızlar sabittir.)', '100', ['90', '110', '90,5'], 'A 1000 m koşarken B 900, C 810 m koşar; C/B = 0,9. B 1000 m\'yi tamamladığında C 900 m koşmuştur: 100 m geride.'),
  ('Bir sayının %p\'si q ise q\'nun %p\'si sayının yüzde kaçıdır?', 'p²/100', ['2p', 'p/100', 'p²'], 'q = (p/100)x; q\'nun %p\'si (p/100)²x = (p²/10.000)x ⇒ x\'in %(p²/100)\'ü.'),
  ('Bir ürünün fiyatı 5 yılda iki katına çıkmıştır. Bir öğrenci yıllık ortalama artışı %20 olarak hesaplıyor. Bu hesap neden hatalıdır?', 'Bileşik artışta yıllık oran %20\'den küçüktür (yaklaşık %14,9).', ['Yıllık artış %40 olmalıdır.', 'Yıllık artış tam %25\'tir.', 'İki katına çıkmak %200 artış demektir.'], '1,2⁵ ≈ 2,49 > 2; 2\'nin beşinci kökü ≈ 1,149 olduğundan yıllık artış ≈ %14,9\'dur.'),
  ('Bir anket “katılımcıların %60\'ı A markasını, %55\'i B markasını kullanıyor” diyor. Bu veriden kesin olarak hangi sonuç çıkar?', 'En az %15\'i iki markayı birlikte kullanıyor.', ['Tam %15\'i iki markayı birlikte kullanıyor.', 'Hiç kimse iki markayı birlikte kullanmıyor.', 'En çok %15\'i iki markayı birlikte kullanıyor.'], '60 + 55 = 115 > 100 olduğundan kesişim en az %15\'tir; en çok %55 olabilir.'),
  ('Bir ormandaki ağaç sayısı her yıl %10 azalıyor. Başlangıca göre kaç yıl sonra ağaç sayısı ilk kez yarının altına iner?', '7', ['5', '6', '10'], '0,9⁶ ≈ 0,531, 0,9⁷ ≈ 0,478 ⇒ 7. yılın sonunda yarının altına iner.'),
  ('İki kardeşten Ayşe\'nin maaşı Mert\'inkinden %20 fazladır. Ayşe\'nin maaşına %10, Mert\'inkine %25 zam yapılırsa kimin maaşı daha fazla olur?', 'Ayşe\'nin maaşı %5,6 fazla olur.', ['Mert\'in maaşı %4 fazla olur.', 'İkisi eşit olur.', 'Ayşe\'nin maaşı %10 fazla olur.'], 'Mert 100 ⇒ Ayşe 120. Zamlarla Mert 125, Ayşe 132: 132/125 = 1,056.'),
  ('Bir ürünün maliyeti 10 TL artırılırsa kâr oranı %50\'den %25\'e düşüyor (satış fiyatı aynı). Ürünün satış fiyatı kaç TL\'dir?', '75', ['60', '50', '62,5'], '1,5M = 1,25(M + 10) ⇒ 0,25M = 12,5 ⇒ M = 50; satış 75 TL.'),
  ('İki kaptan birinde 300 g %20\'lik, diğerinde 200 g %45\'lik tuzlu su vardır. Kaplardaki suların tuz oranlarını eşitlemek için kaplar arasında eşit miktarda (x gram) tuzlu su karşılıklı yer değiştiriliyor. x kaç olmalıdır?', '120', ['100', '150', '112,5'], 'Ortak oran karışımın tamamının oranıdır: (60 + 90)/500 = %30. Birinci kap: 0,2(300 − x) + 0,45x = 0,3 × 300 ⇒ 0,25x = 30 ⇒ x = 120.'),
  ('Tam yağlı süt %3,6, yarım yağlı süt %1,5 yağ içerir. 7 litre yarım yağlı süt elde etmek için tam yağlı süte ne kadar yağsız süt (%0) eklenmelidir?', 'Yaklaşık 4,08 litre', ['3,5 litre', 'Yaklaşık 2,92 litre', '4,2 litre'], 'Tam yağlı süt miktarı t: 0,036t = 0,015 × 7 ⇒ t ≈ 2,92 L. Yağsız süt 7 − 2,92 ≈ 4,08 L.'),
  ('Bir şişedeki 1 litre portakal suyunun %10\'u posadır. Süzgeçten geçirilince posanın %80\'i ayrılıyor. Süzülen sıvıdaki posa oranı yaklaşık yüzde kaçtır?', '%2,2', ['%2', '%8', '%2,25'], 'Posa 100 ml\'den 20 ml kalır; sıvı 1000 − 80 = 920 ml. 20/920 ≈ %2,17.'),
  ('Bir boyacı 8 litre koyu maviye (boyar madde %50) 12 litre beyaz (boyar madde %0) ekliyor. Sonra 5 litre karışımı başka işe ayırıp kalan karışıma 5 litre koyu mavi ekliyor. Son karışımda boyar madde yüzde kaçtır?', '%27,5', ['%23,75', '%30', '%32,5'], 'İlk karışım 20 L\'de 4 L boyar (%20). 5 L ayrılınca 15 L\'de 3 L. 5 L koyu mavi 2,5 L ekler ⇒ 5,5/20 = %27,5.'),
  ('Kilogramı 60 TL olan pirinçten 20 kg ile kilogramı 45 TL olan pirinçten kaç kg karıştırılırsa, karışım kilosu 63 TL\'den satıldığında %20 kâr edilir?', '20', ['15', '10', '12,5'], 'Karışım maliyeti 63/1,2 = 52,5 TL. (1200 + 45x)/(20 + x) = 52,5 ⇒ 1200 + 45x = 1050 + 52,5x ⇒ x = 20 kg.'),
  ('Bir pilot 1500 km\'lik yolu planladığı saatte 600 km hızla uçacakken rüzgâr nedeniyle ilk 600 km\'yi saatte 500 km hızla uçuyor. Planlanan sürede varmak için kalan yolu saatte kaç km hızla uçmalıdır?', '692,3', ['700', '750', '650'], 'Planlanan süre 2,5 saat; ilk 600 km 1,2 saat sürdü. Kalan 900 km 1,3 saatte: 900/1,3 ≈ 692,3 km/sa.'),
  ('Bir otobüs firması iki kent arasında her 40 dakikada bir sefer düzenliyor ve yolculuk 3 saat sürüyor. Yolda karşı yönden gelen otobüslerle de aynı düzende sefer yapılıyorsa bir otobüs yolculuğu boyunca (iki uçtaki anlar hariç) karşı yönden gelen kaç otobüsle karşılaşır?', '9', ['4', '8', '10'], 'Kalkıştan önceki ve sonraki 3 saat içinde karşı kentten kalkan otobüslerle karşılaşılır: (−180, 180) dakika aralığında 40\'ın katları −160…160 olmak üzere 9 değer vardır; bu nedenle 9 otobüsle karşılaşılır.'),
  ('A ile B arasında giden bir araç yolun yarısında 15 dakika mola veriyor. Mola dahil ortalama hızı saatte 60 km, mola hariç sürüş hızı saatte 80 km ise A ile B arası kaç km\'dir?', '60', ['80', '40', '75'], 'x/80 + 0,25 = x/60 ⇒ x(1/60 − 1/80) = 0,25 ⇒ x/240 = 0,25 ⇒ x = 60 km.'),
  ('Bir ürünün fiyatı önce %x artıyor, sonra %x azalıyor (x > 0). Son fiyat ilk fiyata göre nasıldır?', 'İlk fiyattan %x²/100 kadar düşüktür.', ['İlk fiyata eşittir.', 'İlk fiyattan %x²/100 kadar yüksektir.', 'İlk fiyattan %2x kadar düşüktür.'], '(1 + x/100)(1 − x/100) = 1 − x²/10.000 ⇒ ilk fiyattan %(x²/100) düşük.'),
  ('Bir tuzlu suya hem tuz hem su eklendiğinde tuz oranının artması için hangi koşul yeterlidir?', 'Eklenen kısmın tuz oranı, mevcut orandan büyük olmalıdır.', ['Eklenen tuz, eklenen sudan fazla olmalıdır.', 'Eklenen tuz miktarı 10 gramı geçmelidir.', 'Eklenen su, mevcut sudan az olmalıdır.'], 'Yeni oran, eski karışım ile eklenen kısmın ağırlıklı ortalamasıdır; eklenen kısmın oranı büyükse ortalama yükselir.'),
  ('Hileli bir terazi 1 kg yerine 900 g tartıyor. Bu teraziyi kullanan satıcı, malın kilosunu maliyetinin %8 fazlasına satıyorsa gerçek kâr oranı yüzde kaçtır?', '%20', ['%8', '%18', '%17,2'], 'Müşteriye 0,9 kg verilip 1,08M alınır; 1 kg için gelir 1,08/0,9 = 1,2M ⇒ %20 kâr.'),
  ('Akıntılı bir nehirde aynı mesafeyi gidip dönen bir tekne için hangisi doğrudur? (Teknenin durgun sudaki hızı akıntıdan büyüktür.)', 'Akıntı arttıkça gidiş-dönüş süresi uzar.', ['Akıntı gidiş-dönüş süresini etkilemez.', 'Akıntı arttıkça gidiş-dönüş süresi kısalır.', 'Gidiş-dönüş süresi durgun sudakinden kısadır.'], 'Süre d/(v + a) + d/(v − a) = 2dv/(v² − a²); a büyüdükçe payda küçülür, süre uzar.'),
  ('Bir kişi bir mesafeyi gidişte v₁, dönüşte v₂ hızıyla yürüyor. Ortalama hızının hızların aritmetik ortalamasına eşit olabilmesi için ne gerekir?', 'Gidiş ve dönüş hızları eşit olmalıdır.', ['Gidiş hızı dönüşün iki katı olmalıdır.', 'Mesafe 1 km olmalıdır.', 'Dönüş gidişten hızlı olmalıdır.'], 'Eşit yollarda ortalama hız harmonik ortalamadır: 2v₁v₂/(v₁ + v₂). Bu, ancak v₁ = v₂ iken aritmetik ortalamaya eşittir.'),
  ('Yıllık %50 basit faizle borç veren biri, aynı getiriyi bileşik faizle 2 yılda elde etmek isterse yıllık bileşik oran yaklaşık yüzde kaç olmalıdır?', '%41,4', ['%50', '%25', '%44,7'], '2 yılda basit getiri %100 ⇒ (1 + r)² = 2 ⇒ r ≈ 0,414.'),
  ('Bir kitabın yazı boyutu %20 küçültülürse aynı sayfaya sığan harf sayısı yaklaşık yüzde kaç artar?', '%56,25', ['%20', '%25', '%44'], 'Harf alanı 0,8² = 0,64 katına iner; sığan harf sayısı 1/0,64 = 1,5625 katı.'),
  ('Bir pizzacıda 30 cm çaplı pizza 300 TL, 40 cm çaplı pizza 480 TL\'dir. Alan başına fiyat açısından hangisi doğrudur?', 'Büyük pizza yaklaşık %10 daha ucuzdur.', ['Küçük pizza daha ucuzdur.', 'İkisinin alan başına fiyatı eşittir.', 'Büyük pizza %60 daha pahalıdır.'], 'Alanlar oranı (40/30)² = 16/9 ≈ 1,78; fiyat oranı 1,6. Birim fiyat 1,6/1,78 = 0,9 ⇒ %10 ucuz.'),
  ('Aralarında 300 km olan iki kentten aynı anda birbirine doğru saatte 60 ve 90 km hızla çıkan iki araç arasındaki uzaklık ikinci kez 75 km olduğunda yola çıkalı kaç saat olmuştur?', '2,5', ['1,5', '2', '3'], 'Birinci kez 225 km yol alındığında (1,5 saat), ikinci kez karşılaştıktan sonra 375 km toplam yol alındığında olur: 375/150 = 2,5 saat.'),
  ('Bir satıcı iki ürünü toplam 2000 TL\'ye alıyor. Birincisini %20 kârla, ikincisini %10 zararla satıp toplamda %5,75 kâr ediyor. Birinci ürünün maliyeti kaç TL\'dir?', '1050', ['950', '1000', '1150'], '0,2x − 0,1(2000 − x) = 115 ⇒ 0,3x = 315 ⇒ x = 1050.'),
  ('Bir satıcı fiyatı %10 düşürünce satış adedi %30 artıyor. Ürün başına kâr düşüşten önce satış fiyatının %40\'ı ise toplam kâr nasıl değişir?', '%2,5 azalır.', ['%17 artar.', 'Değişmez.', '%2,5 artar.'], 'S = 100, M = 60, kâr 40. Yeni fiyat 90, kâr 30; adet 1,3 kat: 30 × 1,3 = 39 < 40 ⇒ %2,5 azalır.'),
  ('Bir tüccar bir malı x TL\'ye alıp %20 kârla satıyor. Kazandığı parayla aynı maldan aynı fiyata 3 adet daha alabildiğine göre ilk alımda kaç adet mal almıştı?', '15', ['12', '18', '20'], 'Kâr, maliyetin %20\'sidir ve 3 adet mala denk gelir: 0,2n = 3 ⇒ n = 15.'),
  ('İki arkadaş bir arsayı 3 : 5 oranında payla alıyor. Arsa %40 kârla satılınca az paylı olan 180.000 TL kâr payı alıyor. Arsanın alış fiyatı kaç TL\'dir?', '1.200.000', ['1.260.000', '1.440.000', '480.000'], 'Toplam kâr 180.000 × 8/3 = 480.000 TL; 0,4M = 480.000 ⇒ M = 1.200.000.'),
  ('Bir dükkânın kârı her yıl üç ortak arasında 2 : 3 : 4 oranında paylaşılıyor. Bir yıl kâr %50 artınca en büyük paylı ortağın payı 40.000 TL artıyor. Bu yılki toplam kâr kaç TL\'dir?', '270.000', ['180.000', '90.000', '240.000'], 'Toplam artış 40.000 × 9/4 = 90.000 TL; bu eski kârın %50\'si ⇒ eski 180.000, yeni 270.000.'),
  ('Bir anaokulunda öğretmenler 180 kalemi çocuklara eşit dağıtacaklarken 6 çocuğun gelmediğini görüyor; kalemler kalan çocuklara eşit dağıtılınca her çocuğa 1 kalem fazla düşüyor. Gelen çocuk sayısı gelmesi beklenenlerin yüzde kaçıdır?', '%83,3̅', ['%90', '%80', '%85,7'], '180/(n − 6) − 180/n = 1 ⇒ n² − 6n − 1080 = 0 ⇒ n = 36. Gelen 30: 30/36 ≈ %83,3.'),
  ('Bir karışımda A maddesi B maddesinin %60\'ı, C maddesi de A maddesinin %50\'si kadardır. Karışımda yalnız bu üç madde varsa B karışımın yüzde kaçıdır?', '%52,6 (yaklaşık)', ['%60', '%50', '%47,4 (yaklaşık)'], 'B = 1 ⇒ A = 0,6, C = 0,3; toplam 1,9. 1/1,9 ≈ %52,6.'),
  ('Yağ oranı %4 olan sütten %20 yağlı krema ayrıştırılınca geriye yağ oranı %1 olan süt kalıyor. 100 litre sütten kaç litre krema elde edilir?', '15,8', ['20', '3', '12,5'], 'x krema: 0,2x + 0,01(100 − x) = 4 ⇒ 0,19x = 3 ⇒ x ≈ 15,8 L.'),
  ('Bir yaya saatte 5 km hızla yürürken arkasından gelen otobüsler 12 dakikada bir onu geçiyor, karşı yönden gelen otobüslerle 4 dakikada bir karşılaşıyor. Otobüsler eşit aralıklarla ve aynı hızla çalıştığına göre duraklardan kaç dakikada bir otobüs kalkar?', '6', ['8', '4', '7,5'], 'Otobüs hızı v, aralık d: d = 12(v − 5)/60 = 4(v + 5)/60 ⇒ v = 10. d = 1 km; 1/10 saat = 6 dk.'),
  ('Her biri 5 m uzunluğunda 10 araçtan oluşan bir konvoyda ardışık araçlar arasında 15 m boşluk vardır. Konvoy saniyede 10 m hızla 100 m\'lik bir köprüyü tamamen kaç saniyede geçer?', '28,5', ['18,5', '20', '23,5'], 'Konvoy uzunluğu 10 × 5 + 9 × 15 = 185 m. (100 + 185)/10 = 28,5 s.'),
  ('Bir yüzücü 25 m\'lik havuzda saniyede 1,25 m hızla yüzüyor ve her duvara dokunup dönerken 1 saniye kaybediyor. 1000 m\'yi kaç saniyede tamamlar? (Son duvarda dönüş yoktur.)', '839', ['800', '840', '820'], 'Yüzme 1000/1,25 = 800 s. 40 uzunluk, 39 dönüş ⇒ 39 s. Toplam 839 s.'),
  ('Yürüyüşe çıkan biri düz yolda saatte 4 km, yokuş yukarı 3 km, yokuş aşağı 6 km hızla yürüyor. Bir köye gidip aynı yoldan dönüşü 5 saat sürüyorsa köye olan uzaklık kaç km\'dir?', '10', ['12', '8', '7,5'], 'Yokuşta gidiş-dönüş hızlarının harmonik ortalaması 2 × 3 × 6/9 = 4 km/sa ile düz yolunki aynıdır. Toplam 20 km yürünür ⇒ uzaklık 10 km.'),
  ('Bir yürüyüş parkurunun başlangıcından aynı anda iki kardeş çıkıyor. Büyük kardeş parkurun sonuna saatte 6 km hızla varıp hemen geri dönüyor ve saatte 4 km hızla yürüyen küçük kardeşle başlangıçtan 4 km uzakta karşılaşıyor. Parkur kaç km\'dir?', '5', ['6', '4,5', '8'], 'Karşılaşmaya kadar geçen sürede yollar 6 : 4 oranındadır. Küçük kardeş 4 km yürüdüğünde büyük kardeş 6 km yürür: L + (L − 4) = 6 ⇒ L = 5 km.'),
  ('Bir sınıfta kızların %25\'i ile erkeklerin %40\'ı gözlüklüdür ve gözlüklüler sınıfın %31\'idir. Sınıftaki kızların oranı yüzde kaçtır?', '%60', ['%40', '%55', '%62,5'], '0,25k + 0,40(1 − k) = 0,31 ⇒ 0,15k = 0,09 ⇒ k = 0,6.'),
  ('Bir şirketin çalışanlarının %70\'i İngilizce, %45\'i Almanca biliyor; %10\'u ikisini de bilmiyor. Yalnız Almanca bilenler yüzde kaçtır?', '%20', ['%25', '%35', '%15'], 'En az birini bilen %90; ikisini bilen 70 + 45 − 90 = %25. Yalnız Almanca 45 − 25 = %20.'),
  ('Bir mağaza kışın bir montu etiket fiyatından %40 indirimle satıyor, ilkbaharda indirimli fiyatı %25 daha indiriyor. Bu son fiyat maliyete göre %10 zarar ettiriyorsa etiket fiyatı maliyetin yüzde kaç fazlasıdır?', '%100', ['%80', '%65', '%120'], 'E × 0,6 × 0,75 = 0,45E = 0,9M ⇒ E = 2M ⇒ %100 fazla.'),
  ('Bir şehirde araçların %20\'si dizel, kalanı benzinlidir. Bir yılda dizel araç sayısı %50 artıp benzinliler %10 azalınca dizel araçların oranı yüzde kaç olur?', '%29,4 (yaklaşık)', ['%30', '%25', '%33,3 (yaklaşık)'], 'Dizel 20 → 30, benzinli 80 → 72; 30/102 ≈ %29,4.'),
  ('Bir ürünün fiyatı her ay bir önceki aya göre %10 artıyor. Fiyatın ilk kez iki katını aşması kaçıncı ayın sonunda olur?', '8', ['7', '10', '6'], '1,1⁷ ≈ 1,949; 1,1⁸ ≈ 2,144 ⇒ 8. ayın sonunda.'),
  ('Bir sayı %a artırılıp sonra %a azaltılınca %4 küçülüyor. a kaçtır?', '20', ['4', '2', '40'], '1 − a²/10.000 = 0,96 ⇒ a² = 400 ⇒ a = 20.'),
  ('Bir çalışan maaşının %20\'sini biriktiriyor. Maaşı %25 artınca harcamalarını %10 artırıyor. Yeni maaşının yüzde kaçını biriktirir?', '%29,6', ['%30', '%35', '%28,5'], 'Eski: maaş 100, harcama 80. Yeni: maaş 125, harcama 88; birikim 37 ⇒ 37/125 = %29,6.'),
  ('Bir tüccar bir malın etiket fiyatını maliyetin %50 fazlası belirliyor. Müşterilerin yarısına etiket fiyatından, diğer yarısına %20 indirimle satıyor. Toplam kâr oranı yüzde kaçtır?', '%35', ['%30', '%40', '%25'], 'Ortalama satış 1,5M × (1 + 0,8)/2 = 1,35M ⇒ %35 kâr.'),
  ('Bir satıcı malını satış fiyatı üzerinden %20 indirimle satınca maliyete göre %4 kâr ediyor. İndirim %10 olsaydı kâr oranı yüzde kaç olurdu?', '%17', ['%14', '%20', '%18,5'], '0,8S = 1,04M ⇒ S = 1,3M. 0,9S = 1,17M ⇒ %17 kâr.'),
  ('Bir kapta %30\'luk 60 g tuzlu su vardır. Kaptan kaç gram alınıp yerine aynı miktarda %60\'lık tuzlu su konursa karışım %40\'lık olur?', '20', ['15', '30', '24'], 'Oran 30\'dan 40\'a çıkıyor: x(0,6 − 0,3) = 60 × 0,1 ⇒ x = 20 g.'),
  ('A kabında 6 litre su, B kabında 6 litre süt var. A\'dan 2 litre alınıp B\'ye konuyor ve karıştırılıyor; sonra B\'den 2 litre alınıp A\'ya konuyor. A\'daki süt miktarı ile B\'deki su miktarı arasındaki ilişki nedir?', 'Eşittir.', ['A\'daki süt daha fazladır.', 'B\'deki su daha fazladır.', 'Oran 2 : 3\'tür.'], 'Kaplar başlangıçtaki hacimlerine döndüğü için A\'ya geçen süt, B\'ye geçen suya eşit olmak zorundadır (1,5 L).'),
  ('%20\'lik ve %50\'lik iki tuzlu sudan oluşan karışıma 100 g su eklenince oran %25, 100 g tuz eklenince oran %50 oluyor. Karışım başlangıçta kaç gramdır?', '300', ['200', '250', '400'], 'Tuz t, kütle m: t = 0,25(m + 100) ve t + 100 = 0,5(m + 100). Taraf tarafa çıkarılınca 100 = 0,25(m + 100) ⇒ m = 300 (t = 100).'),
  ('A ve B\'den aynı anda birbirine doğru yola çıkan iki araç ilk kez A\'dan 60 km uzakta karşılaşıyor. Karşı uçlara varıp hemen geri dönen araçlar ikinci kez B\'den 30 km uzakta karşılaşıyor. A ile B arası kaç km\'dir?', '150', ['120', '180', '90'], 'İlk karşılaşmada toplam yol d, ikincide 3d\'dir. A\'dan çıkan araç ilk buluşmaya kadar 60 km aldıysa ikinciye kadar 180 km alır: 180 = d + 30 ⇒ d = 150.'),
  ('Bir araç yolun ilk yarısını saatte 60 km ile gidiyor. Bütün yoldaki ortalama hızın saatte 72 km olması için ikinci yarıyı saatte kaç km ile gitmelidir?', '90', ['84', '80', '96'], '2/72 = 1/60 + 1/v ⇒ 1/v = 1/36 − 1/60 = 1/90 ⇒ v = 90.'),
  ('Bir motor akıntı yönünde 36 km gidip geri dönüyor ve toplam 5 saat harcıyor. Akıntının hızı saatte 3 km ise motorun durgun sudaki hızı saatte kaç km\'dir?', '15', ['12', '18', '13,5'], '36/(v + 3) + 36/(v − 3) = 5 ⇒ 72v = 5v² − 45 ⇒ 5v² − 72v − 45 = 0 ⇒ v = 15.'),
  ('Bir otobüs saat 09.00\'da A\'dan B\'ye, bir minibüs aynı saatte B\'den A\'ya hareket ediyor. Karşılaştıklarında saat 11.00\'dir; otobüs B\'ye 12.00\'de varıyor. Minibüs A\'ya saat kaçta varır?', '15.00', ['14.00', '13.00', '16.00'], 'Karşılaşmadan sonra otobüs 1 saat gider; t² = t₁ × t₂ ⇒ 2² = 1 × t₂ ⇒ minibüs 4 saat daha gider: 15.00.'),
  ('A\'dan B\'ye saatte 40 km hızla bir kamyon, aynı anda B\'den A\'ya saatte 60 km hızla bir otomobil yola çıkıyor. Kamyon, otomobille karşılaştıktan 1 saat 30 dakika sonra B\'ye varıyor. A ile B arası kaç km\'dir?', '100', ['150', '120', '90'], 'Karşılaşmadan sonra kamyonun kalan yolu, otomobilin karşılaşmaya kadar aldığı yoldur: 60t = 40 × 1,5 ⇒ t = 1 saat. Uzaklık (40 + 60) × 1 = 100 km.'),
  ('Bir dağcı zirveye çıkarken her 100 m yükseklikte hava sıcaklığının yaklaşık 0,6 °C düştüğünü biliyor. Deniz seviyesinde 18 °C olan bir günde 2500 m\'deki sıcaklık yaklaşık kaç °C\'dir? Bu düşüş, deniz seviyesi sıcaklığının yüzde kaçıdır?', '3 °C; %83,3', ['15 °C; %16,7', '3 °C; %16,7', '6 °C; %66,7'], '2500 m\'de düşüş 25 × 0,6 = 15 °C ⇒ 3 °C. 15/18 ≈ %83,3.'),
  ('Bir satıcı malın maliyetini %15 düşürmeyi başarıyor ve satış fiyatını değiştirmiyor. Eskiden %2 olan kâr oranı yüzde kaç olur?', '%20', ['%17', '%15', '%18,5'], 'M = 100, S = 102. Yeni maliyet 85: kâr 17/85 = %20.'),
  ('Bir tren 480 km\'lik yolu planlanandan saatte 20 km daha hızlı giderek 2 saat erken tamamlıyor. Trenin planlanan hızı saatte kaç km\'dir?', '60', ['80', '40', '48'], '480/v − 480/(v + 20) = 2 ⇒ v² + 20v − 4800 = 0 ⇒ v = 60.'),
];
